(function(){var ns2=$.namespace("pskl.controller.settings.exportimage");ns2.ZipExportController=function(piskelController,exportController){this.piskelController=piskelController;this.exportController=exportController};pskl.utils.inherit(ns2.ZipExportController,pskl.controller.settings.AbstractSettingController);ns2.ZipExportController.prototype.init=function(){this.pngFilePrefixInput=document.querySelector(".zip-prefix-name");this.pngFilePrefixInput.value="sprite_";this.splitByLayersCheckbox=document.querySelector(".zip-split-layers-checkbox");this.addEventListener(this.splitByLayersCheckbox,"change",this.onSplitLayersClick_);this.useLayerNamesContainer=document.querySelector(".use-layer-names-container");this.useLayerNamesCheckbox=document.querySelector(".zip-use-layer-names-checkbox");this.toggleHideUseLayerNamesCheckbox();var zipButton=document.querySelector(".zip-generate-button");this.addEventListener(zipButton,"click",this.onZipButtonClick_)};ns2.ZipExportController.prototype.toggleHideUseLayerNamesCheckbox=function(){this.useLayerNamesContainer.style.display=this.splitByLayersCheckbox.checked?"block":"none"};ns2.ZipExportController.prototype.onSplitLayersClick_=function(){this.toggleHideUseLayerNamesCheckbox()};ns2.ZipExportController.prototype.onZipButtonClick_=function(){var zip=new window.JSZip;if(this.splitByLayersCheckbox.checked){this.splittedExport_(zip)}else{this.mergedExport_(zip)}var fileName=this.getPiskelName_()+".zip";var blob=zip.generate({type:"blob"});pskl.utils.FileUtils.downloadAsFile(blob,fileName)};ns2.ZipExportController.prototype.mergedExport_=function(zip){var paddingLength=(""+this.piskelController.getFrameCount()).length;var zoom=this.exportController.getExportZoom();for(var i=0;i<this.piskelController.getFrameCount();i++){var render=this.piskelController.renderFrameAt(i,true);var canvas=pskl.utils.ImageResizer.scale(render,zoom);var basename=this.pngFilePrefixInput.value;var id=pskl.utils.StringUtils.leftPad(i,paddingLength,"0");var filename=basename+id+".png";zip.file(filename,pskl.utils.CanvasUtils.getBase64FromCanvas(canvas)+"\n",{base64:true})}};ns2.ZipExportController.prototype.splittedExport_=function(zip){var layers=this.piskelController.getLayers();var framePaddingLength=(""+this.piskelController.getFrameCount()).length;var layerPaddingLength=(""+layers.length).length;var zoom=this.exportController.getExportZoom();for(var j=0;this.piskelController.hasLayerAt(j);j++){var layer=this.piskelController.getLayerAt(j);var layerid=pskl.utils.StringUtils.leftPad(j,layerPaddingLength,"0");for(var i=0;i<this.piskelController.getFrameCount();i++){var render=pskl.utils.LayerUtils.renderFrameAt(layer,i,true);var canvas=pskl.utils.ImageResizer.scale(render,zoom);var basename=this.pngFilePrefixInput.value;var frameid=pskl.utils.StringUtils.leftPad(i+1,framePaddingLength,"0");var filename="l"+layerid+"_"+basename+frameid+".png";if(this.useLayerNamesCheckbox.checked){filename=layer.getName()+"_"+basename+frameid+".png"}zip.file(filename,pskl.utils.CanvasUtils.getBase64FromCanvas(canvas)+"\n",{base64:true})}}};ns2.ZipExportController.prototype.getPiskelName_=function(){return this.piskelController.getPiskel().getDescriptor().name}})();;
