(function(){var ns2=$.namespace("pskl.controller.dialogs.backups.steps");var PREVIEW_SIZE=60;ns2.SessionDetails=function(piskelController,backupsController,container){this.piskelController=piskelController;this.backupsController=backupsController;this.container=container};ns2.SessionDetails.prototype.init=function(){this.backButton=this.container.querySelector(".back-button");this.addEventListener(this.backButton,"click",this.onBackClick_);this.addEventListener(this.container,"click",this.onContainerClick_)};ns2.SessionDetails.prototype.destroy=function(){pskl.utils.Event.removeAllEventListeners(this)};ns2.SessionDetails.prototype.addEventListener=function(el,type,cb){pskl.utils.Event.addEventListener(el,type,cb,this)};ns2.SessionDetails.prototype.onShow=function(){var sessionId=this.backupsController.backupsData.selectedSession;pskl.app.backupService.getSnapshotsBySessionId(sessionId).then(function(snapshots){var html=this.getMarkupForSnapshots_(snapshots);this.container.querySelector(".snapshot-list").innerHTML=html;snapshots.forEach(function(snapshot){this.updateSnapshotPreview_(snapshot)}.bind(this))}.bind(this)).catch(function(){var html=pskl.utils.Template.get("snapshot-list-error");this.container.querySelector(".snapshot-list").innerHTML=html}.bind(this))};ns2.SessionDetails.prototype.getMarkupForSnapshots_=function(snapshots){if(snapshots.length===0){console.warn("Could not retrieve snapshots for a session");return pskl.utils.Template.get("snapshot-list-empty")}var sessionItemTemplate=pskl.utils.Template.get("snapshot-list-item");return snapshots.reduce(function(previous,snapshot){var view={id:snapshot.id,name:snapshot.name,description:snapshot.description?"- "+snapshot.description:"",date:pskl.utils.DateUtils.format(snapshot.date,"the {{Y}}/{{M}}/{{D}} at {{H}}:{{m}}"),frames:snapshot.frames===1?"1 frame":snapshot.frames+" frames",resolution:pskl.utils.StringUtils.formatSize(snapshot.width,snapshot.height),fps:snapshot.fps};return previous+pskl.utils.Template.replace(sessionItemTemplate,view)},"")};ns2.SessionDetails.prototype.updateSnapshotPreview_=function(snapshot){pskl.utils.serialization.Deserializer.deserialize(JSON.parse(snapshot.serialized),function(piskel){var selector='.snapshot-item[data-snapshot-id="'+snapshot.id+'"] .snapshot-preview';var previewContainer=this.container.querySelector(selector);if(!previewContainer){return}var image=this.getFirstFrameAsImage_(piskel);previewContainer.appendChild(image)}.bind(this))};ns2.SessionDetails.prototype.getFirstFrameAsImage_=function(piskel){var frame=pskl.utils.LayerUtils.mergeFrameAt(piskel.getLayers(),0);var wZoom=PREVIEW_SIZE/piskel.width;var hZoom=PREVIEW_SIZE/piskel.height;var zoom=Math.min(hZoom,wZoom);return pskl.utils.FrameUtils.toImage(frame,zoom)};ns2.SessionDetails.prototype.onBackClick_=function(){this.backupsController.back(this)};ns2.SessionDetails.prototype.onContainerClick_=function(evt){var action=evt.target.dataset.action;if(action=="load"&&window.confirm(Constants.CONFIRM_OVERWRITE)){var snapshotId=evt.target.dataset.snapshotId*1;pskl.app.backupService.loadSnapshotById(snapshotId).then(function(){$.publish(Events.DIALOG_HIDE)})}}})();;
